import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        nextInt();
        int rate = nextInt();
        String s = next();
        long a = 0, p = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 'A') a++;
            else if (s.charAt(i) == 'P') p++;
        }
        // Each conversion is one cycle and creates one A that later costs another cycle.
        System.out.println(a + 2 * (p / rate));
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	readInt()
	rate := readInt()
	s := readToken()
	a, p := strings.Count(s, "A"), strings.Count(s, "P")
	// Each conversion is one cycle and creates one A that later costs another cycle.
	fmt.Println(a + 2*(p/rate))
}
